                    ["record.cancelsave.tip"] = "用快捷鍵放棄目前這一局待存的回放。關掉這一項，下面那個快捷鍵就整條失效。",
                    ["record.asyncinput.tip"] = "從遊戲的非同步輸入系統取按鍵，時間戳更準。需要先在遊戲設定裡開啟非同步輸入，否則勾了也不生效。",
                    ["record.keybd.record.tip"] = "把按鍵的「嗒嗒」聲一起錄成獨立音軌，回放時能聽到。",
