                    ["record.keybd.compact.tip"] = "勾選後鍵盤音以 8 kHz 存進回放檔案，體積約為預設檔的一半，聽感略悶；預設檔是 16 kHz。只影響之後新儲存的回放。",
                    ["record.savekey.tip"] = "手動保存本局的快捷鍵，預設 F9。點一下它再按任意鍵即可改綁。",
