                    ["render.surface.tip"] = "畫面來源。「純淨相機」不含 UI 且解析度任意；「遊戲畫面」含 UI 且跟隨視窗。",
                    ["render.cursor.tip"] = "把滑鼠指標畫進成片。新錄製的回放會一併記下指標軌跡，渲染時按歌曲時間回放——與畫面同源，不受渲染速度與波動影響；舊回放沒有軌跡，回落到渲染時的活體指標（快慢隨渲染速度波動）。指標被系統隱藏時不畫。",
                    ["render.codec.tip"] = "編碼器選擇。「最快」優先使用顯示卡硬體編碼，偵測失敗會退回 CPU——速度差一個數量級，實際使用的那個顯示在下面那行。",
                    ["render.quality.tip"] = "編碼畫質。越高檔案越大，渲染耗時也略增。",
