                    ["render.clock.hint"] = "ゲームが参照する時間源をフレーム番号駆動の仮想クロックに置き換え、ビートの進行、カメライベント、カウントダウン、キーサウンドのスケジューリングを決定的にします。出力フレームレートはマシン負荷に関係なく一定になります。オフ = オーディオカーソルによるフォールバック：レンダリングは動作しますが、タイムラインはオーディオカーソル駆動（ミリ秒単位の揺らぎあり）になり、映像背景もレンダリング速度に合わせた速度調整が行われなくなります。注意：ゲーム自身の時間源を変更するため影響範囲が広くなります。他の動画レンダリング系モッドが同時に有効な場合、同じパッチ箇所を奪い合い（先に読み込んだ方が有効）、このオプションは自動的に譲ります。レンダリングエラーや音ズレが出た場合は、まずこれをオフにしてください。",
