                    ["about.debug.skipverify.tip"] = "リプレイと音声の整合性チェックを省きます。ファイルが改変されている場合や、録画時とフレームタイミングが違う場合（シェーダーや時間源を変更した）にだけ必要です。壊れたリプレイを見つける第一の防波堤なので、異常がないときは切らないでください。",
