                    ["effects.enablesave.tip"] = "효과 제거가 활성화된 상태에서 현재 채보를 디스크에 다시 쓰도록 허용합니다. 기본값은 끄기: 원본 파일을 덮어쓰며 되돌릴 수 없습니다.",
