                    ["effects.resettrackcolor.tip"] = "트랙 스타일과 색을 기본 주황색 표준 트랙으로 되돌립니다.",
                    ["effects.toggleall.tip"] = "이 그룹에 하나라도 켜져 있으면 한 번에 모두 끄고, 모두 꺼져 있으면 한 번에 모두 켭니다. 대상은 '해당 종류의 이벤트를 제거'하는 스위치뿐이며, 초기화 항목과 부속 옵션은 포함되지 않습니다.",
                    ["effects.planetorbit.tip"] = "행성 공전 이벤트를 제거합니다.",
