                    ["effects.framerate.tip"] = "프레임레이트 변경 이벤트를 제거해 레벨 전체가 한 가지 프레임레이트로 실행되게 합니다.",
                    ["effects.repeatevents.tip"] = "반복 이벤트를 제거합니다. 채보가 이를 통해 재사용하던 구간은 한 번 펼쳐집니다.",
                    ["record.recording.tip"] = "마스터 스위치. 끄면 레벨에 들어가도 아무 키도 기록되지 않습니다.",
                    ["record.autosave.tip"] = "레벨을 클리어하면 이번 런을 리플레이 파일로 저장합니다.",
