                    ["record.dontsavewhenauto.tip"] = "게임이 자동으로 플레이한 레벨은 저장하지 않아 자동 플레이로 리플레이 목록이 넘치지 않습니다.",
                    ["record.dontsavewhenmiss.tip"] = "미스가 있는 런은 저장하지 않습니다. 실패한 시도를 남기려면 끄세요.",
