                    ["record.failsave.tip"] = "중간에 사망해도 저장합니다. 기본적으로는 클리어 시 또는 수동 저장 시에만 파일을 씁니다.",
                    ["record.backup.tip"] = "저장할 때 추가 복사본을 남겨 같은 이름의 기존 파일이 그대로 덮어써지지 않습니다.",
                    ["record.manualsave.tip"] = "F9로 현재 런을 수동 저장할 수 있게 합니다. 연습 중간에도 저장됩니다.",
                    ["record.cancelsave.tip"] = "단축키로 현재 런의 대기 중인 저장을 버립니다. 이 항목을 끄면 아래 단축키가 작동하지 않습니다.",
                    ["record.asyncinput.tip"] = "게임의 비동기 입력에서 키를 읽어 타임스탬프를 더 정확하게 합니다. 게임에서 비동기 입력을 먼저 켜야 하며, 그렇지 않으면 아무 효과도 없습니다.",
                    ["record.keybd.record.tip"] = "키를 누른 탭 소리를 별도 트랙으로 녹음해 재생할 때 키사운드가 들리게 합니다.",
                    ["record.keybd.volume.tip"] = "재생 중 키보드 소리의 볼륨. 0 = 무음.",
                    ["record.keybd.offset.tip"] = "키보드 소리 전체의 어긋남을 보정합니다. 빠르면 음수, 늦으면 양수, 단위는 밀리초입니다.",
                    ["record.keybd.compact.tip"] = "켜면 키보드음이 8 kHz로 리플레이 파일에 저장됩니다. 크기는 기본의 절반 정도이고 소리는 약간 먹먹해집니다. 기본은 16 kHz이며 이후에 저장하는 리플레이에만 적용됩니다.",
                    ["record.savekey.tip"] = "이번 런을 저장하는 단축키로 기본값은 F9입니다. 클릭한 뒤 아무 키나 누르면 다시 지정됩니다.",
                    ["record.cancelsavekey.tip"] = "이번 런의 대기 중인 저장을 버리는 단축키입니다.",
                    ["render.on.tip"] = "동영상 렌더링 마스터 스위치. 끄면 새 렌더링을 시작할 수 없습니다.",
                    ["render.width.tip"] = "출력 너비. 클린 카메라에서만 사용되며 게임 화면은 창 크기를 따릅니다.",
                    ["render.height.tip"] = "출력 높이. 클린 카메라에서만 사용됩니다.",
                    ["render.fps.tip"] = "출력 프레임레이트. 높을수록 부드럽고 렌더링 시간도 비례해 늘어납니다.",
                    ["render.tail.tip"] = "레벨 종료 후 추가로 녹화하는 초. 아웃트로 애니메이션을 담기 위한 것입니다.",
                    ["render.surface.tip"] = "프레임 소스. 클린 카메라는 UI가 없고 해상도가 자유로우며, 게임 화면은 UI를 포함하고 창을 따릅니다.",
                    ["render.cursor.tip"] = "마우스 커서를 영상에 그립니다. 새로 기록된 리플레이는 커서 궤적도 함께 저장하며, 렌더링 시 곡 타임라인을 따라 재생됩니다. 화면과 같은 시간축이라 렌더링 속도의 영향을 받지 않습니다. 이전 리플레이에는 궤적이 없어 렌더링 시점의 실제 커서로 대체됩니다(속도는 렌더링 속도를 따름). 숨겨진 커서는 그려지지 않습니다.",
                    ["render.codec.tip"] = "인코더 선택. “가장 빠름”은 GPU 인코딩을 우선하고 감지에 실패하면 CPU로 돌아갑니다. 속도 차이가 크며 실제 사용 중인 것은 아래 줄에 표시됩니다.",
                    ["render.quality.tip"] = "인코딩 화질. 높을수록 파일이 커지고 렌더링 시간도 조금 늘어납니다.",
                    ["render.format.tip"] = "출력 파일의 컨테이너 형식. mp4가 가장 호환성이 높고, webm은 작지만 재인코딩이 필요합니다.",
                    ["render.outdir.tip"] = "완성된 영상의 저장 위치. 비워 두면 = 모드 폴더 아래 RenderVideos.",
                    ["render.clock.experimental.tip"] = "게임이 읽는 시간 소스를 프레임 인덱스 기반 가상 시계로 교체해 기기 부하와 무관하게 출력 프레임레이트를 일정하게 유지합니다. 게임 자체의 시간 소스를 바꾸므로 영향 범위가 넓으며, 렌더링 오류나 음성/영상 어긋남이 보이면 먼저 이 옵션을 끄세요.",
                    ["convert.target.tip"] = "출력 폴더에 있는 기존 동영상을 이 형식으로 변환합니다. 위의 렌더링 형식과는 별개입니다.",
                    ["render.start.tip"] = "현재 설정으로 렌더링을 시작합니다. 먼저 리플레이를 불러오고 해당 레벨에 들어가야 합니다.",
                    ["render.cancel.tip"] = "현재 렌더링을 중단합니다. 이미 기록된 부분은 유지됩니다.",
                    ["convert.button.tip"] = "출력 폴더의 동영상 일괄 변환을 시작합니다.",
                    ["record.changedir.tip"] = "리플레이 저장 폴더를 변경합니다. 녹화 중에는 변경할 수 없으며, 변경하면 이번 런의 키보드 소리를 찾을 수 없게 됩니다.",
