                    ["render.surface.clean_note"] = "Sin UI alguna, cualquier resolución de salida (se permite supermuestreo); ideal para metraje puro o material de edición.",
                    ["render.clock.experimental"] = "Reloj de renderizado determinista (experimental)",
                    ["render.clock.hint"] = "Sustituye la fuente de tiempo que lee el juego por un reloj virtual basado en el índice de fotograma, haciendo deterministas el avance de los tiempos, los eventos de cámara, las cuentas atrás y la programación de los sonidos de tecla: la tasa de fotogramas de salida se mantiene constante sin importar la carga de la máquina. Desactivado = respaldo por cursor de audio: el renderizado sigue funcionando, pero la línea de tiempo la marca el cursor de audio (fluctuación de milisegundos) y los fondos de vídeo ya no se ajustan a la velocidad de renderizado. Nota: modifica la propia fuente de tiempo del juego, así que su alcance es mayor que otras opciones; si otro mod de renderizado de vídeo está activo a la vez, ambos compiten por el mismo punto de parcheo (gana el primero en cargar) y esta opción cede automáticamente. Si el renderizado falla o hay desfase de audio/vídeo, desactívala primero.",
