                    ["about.debug.oldhit"] = "Usar el juicio antiguo",
                    ["about.debug.skipverify.tip"] = "Omite la comprobación de integridad del replay y del audio. Solo hace falta si el archivo fue modificado o si el tiempo de fotograma difiere del de grabación (shaders o fuente de tiempo cambiados). No lo actives si todo funciona: es la primera defensa contra replays corruptos.",
                    ["about.debug.hidetext.tip"] = "No muestra los avisos de la parte inferior. Útil al grabar vídeo, capturar imágenes limpias o cuando tu propia salida de depuración estorba; a cambio, tampoco avisará de fallos silenciosos, como una acción que no tuvo efecto.",
                    ["about.debug.noencryption.tip"] = "Guarda los replays como .psprp sin cifrar para poder inspeccionar el contenido con herramientas normales. El mod los sigue cargando, pero no tienen protección de integridad (cualquiera puede editarlos): no los uses para compartir ni como copia de seguridad.",
                    ["about.debug.oldhit.tip"] = "Recalcula los juicios con la ruta antigua para comprobar si la nueva puntúa mal algún golpe concreto. Solo afecta a lo que se muestra durante la reproducción; los datos grabados no cambian.",
