                    ["effects.repeatevents"] = "Repetir eventos",
                    ["effects.gameplay.note"] = "Este grupo cambia el propio juego. Sin puntos de control ni eventos de entrada, el mapa deja de ser lo mismo que el original. Actívalos solo cuando quieras mirar únicamente las pistas.",
                    ["effects.on.tip"] = "Interruptor maestro. Cuando está desactivado, el mapa cargado coincide exactamente con los datos originales; no se quita ni un solo evento.",
                    ["effects.enablesave.tip"] = "Permite escribir el mapa actual en disco mientras la eliminación de efectos está activa. Desactivado por defecto: sobrescribe el archivo original y no se puede deshacer.",
                    ["effects.filters.tip"] = "Quita filtros de pantalla completa como destello, temblor de pantalla, caleidoscopio, bloom y mosaico de pantalla.",
                    ["effects.advfilters.tip"] = "Quita los eventos de filtros avanzados. Separado de los filtros normales de arriba para que puedas conservar solo un tipo.",
                    ["effects.particles.tip"] = "Quita los eventos que añaden, emiten o configuran partículas.",
                    ["effects.backgrounds.tip"] = "Quita los fondos personalizados y vacía el vídeo de fondo, dejando un color plano.",
                    ["effects.cameras.tip"] = "Quita los eventos de movimiento de cámara para que la cámara se quede quieta.",
                    ["effects.setcamerazoom.tip"] = "Bloquea la cámara en un zoom fijo una vez quitados los movimientos de cámara. El zoom de abajo no hace nada si esto está desactivado.",
                    ["effects.camerazoom.tip"] = "Nivel de zoom al que bloquear la cámara. Solo se aplica si «Fijar zoom de cámara» de arriba está activado.",
                    ["effects.decorations.tip"] = "Elimina decoraciones, texto y objetos personalizados del mapa.",
                    ["effects.removealldecor.tip"] = "Vacía todas las decoraciones. Cuando está desactivado, se conservan las referenciadas por eventos condicionales.",
                    ["effects.trackanim.tip"] = "Quita las animaciones de aparición y desaparición de pistas para que aparezcan de inmediato.",
                    ["effects.trackpos.tip"] = "Quita los eventos de posición de las pistas.",
                    ["effects.trackmove.tip"] = "Quita los eventos de movimiento de pista, el tipo más común de movimiento de pista.",
                    ["effects.trackcolor.tip"] = "Quita los eventos de color de pista para que las pistas mantengan un solo color.",
                    ["effects.resettrackopacity.tip"] = "Devuelve al 100 % la opacidad de los eventos de movimiento de pista que queden.",
                    ["effects.resettrackanim.tip"] = "Restablece las animaciones de aparición y desaparición de pistas a un fundido, para que las pistas no desaparezcan tras quitar sus animaciones.",
                    ["effects.resettrackcolor.tip"] = "Restablece el estilo y el color de la pista a la pista estándar naranja por defecto.",
                    ["effects.toggleall.tip"] = "Si algún interruptor de este grupo está activo, una pulsación los desactiva todos; si todos están desactivados, una pulsación los activa todos. Solo incluye los interruptores que quitan un tipo de evento; los de reinicio y las opciones asociadas quedan fuera.",
                    ["effects.planetorbit.tip"] = "Quita los eventos de órbita del planeta.",
                    ["effects.planetscale.tip"] = "Quita los eventos de escala del planeta.",
                    ["effects.planetradius.tip"] = "Quita los eventos de radio del planeta.",
                    ["effects.hideicons.tip"] = "Quita los eventos de ocultar iconos.",
                    ["effects.hitsounds.tip"] = "Quita los sonidos de golpe y los eventos de sonido personalizado. La canción se queda en silencio.",
                    ["effects.holdsounds.tip"] = "Quita los eventos de sonido de mantenimiento.",
                    ["effects.checkpoints.tip"] = "Quita los puntos de control, así que un fallo a mitad del nivel te devuelve al principio.",
                    ["effects.inputevents.tip"] = "Quita los eventos de entrada, como la reproducción automática y los límites de teclas.",
                    ["effects.framerate.tip"] = "Quita los eventos de cambio de tasa de fotogramas para que todo el nivel vaya a una sola tasa.",
                    ["effects.repeatevents.tip"] = "Quita los eventos de repetición. Las secciones que el mapa reutiliza a través de ellos se expanden una vez.",
                    ["record.recording.tip"] = "Interruptor maestro. Cuando está desactivado, entrar en un nivel no registra nada.",
                    ["record.autosave.tip"] = "Guarda esta partida como archivo de repetición al terminar el nivel.",
                    ["record.completesave.tip"] = "Guardar solo partidas completadas por entero. Desactívalo para conservar también las partidas abandonadas a medias.",
                    ["record.dontsavewhenauto.tip"] = "Omite los niveles que el juego reprodujo solo, para que la reproducción automática no inunde tu lista de repeticiones.",
                    ["record.dontsavewhenmiss.tip"] = "Omite las partidas que contengan un fallo. Desactívalo para conservar un intento fallido.",
                    ["record.latesave.tip"] = "Guarda al salir del nivel en lugar de en la pantalla de resultados.",
                    ["record.failsave.tip"] = "Guarda también al morir. Por defecto solo se escribe un archivo al completar o con el guardado manual.",
                    ["record.backup.tip"] = "Conserva una copia extra al guardar, para que un archivo existente con el mismo nombre no se sobrescriba directamente.",
                    ["record.manualsave.tip"] = "Permite guardar la partida actual manualmente con F9, incluso a mitad de un entrenamiento.",
                    ["record.cancelsave.tip"] = "Descarta con una tecla la partida pendiente de guardar. Si lo desactivas, la tecla de abajo no hace nada.",
                    ["record.asyncinput.tip"] = "Lee las teclas de la entrada asíncrona del juego para tener marcas de tiempo más precisas. Primero debe estar activada la opción de entrada asíncrona del juego, o esto no hará nada.",
                    ["record.keybd.record.tip"] = "Graba el sonido de las pulsaciones como pista aparte para que la reproducción tenga sonidos de teclado.",
                    ["record.keybd.volume.tip"] = "Volumen del sonido de teclado durante la reproducción. 0 = silenciado.",
                    ["record.keybd.offset.tip"] = "Calibra el sonido de teclado en conjunto: negativo si suena pronto, positivo si suena tarde, en milisegundos.",
                    ["record.keybd.compact.tip"] = "Si se activa, el sonido del teclado se guarda a 8 kHz dentro del archivo de repetición: cerca de la mitad de tamaño y algo más apagado. Por defecto son 16 kHz. Solo afecta a las repeticiones guardadas después.",
                    ["record.savekey.tip"] = "Atajo para guardar esta partida; F9 por defecto. Haz clic en él y pulsa cualquier tecla para reasignarlo.",
                    ["record.cancelsavekey.tip"] = "Atajo que descarta el guardado pendiente de esta partida.",
                    ["render.on.tip"] = "Interruptor maestro del renderizado de vídeo. Desactivado, no se puede iniciar un nuevo renderizado.",
                    ["render.width.tip"] = "Ancho de salida. Solo lo usa la cámara limpia; la pantalla del juego sigue el tamaño de la ventana.",
                    ["render.height.tip"] = "Altura de salida. Solo lo usa la cámara limpia.",
                    ["render.fps.tip"] = "Tasa de fotogramas de salida. Más alta significa más fluido, y el tiempo de renderizado crece proporcionalmente.",
                    ["render.tail.tip"] = "Segundos extra grabados tras terminar el nivel, para conservar la animación final.",
                    ["render.surface.tip"] = "Fuente de imagen. La cámara limpia no tiene UI y admite cualquier resolución; la pantalla del juego incluye la UI y sigue la ventana.",
                    ["render.cursor.tip"] = "Dibuja el cursor del ratón en el vídeo. Los replays recién grabados también guardan la trayectoria del cursor, que se reproduce siguiendo la línea de tiempo de la canción: sincronizada con la imagen e independiente de la velocidad de renderizado. Los replays antiguos no tienen trayectoria y usan el cursor en vivo del momento del render (su ritmo sigue la velocidad de renderizado). Un cursor oculto no se dibuja.",
                    ["render.codec.tip"] = "Elección de codificador. «Más rápido» prefiere la codificación por GPU y recurre a la CPU si la detección falla; la fila de abajo muestra cuál se está usando realmente.",
                    ["render.quality.tip"] = "Calidad de codificación. Más alta da archivos más grandes y renderizados algo más lentos.",
