                    ["render.outdir.tip"] = "Dónde van los vídeos terminados. Vacío = RenderVideos en la carpeta del mod.",
                    ["render.clock.experimental.tip"] = "Sustituye la fuente de tiempo del juego por un reloj virtual basado en el índice de fotograma para que la tasa de fotogramas de salida se mantenga constante sin importar la carga de la máquina. Modifica la propia fuente de tiempo del juego, así que su alcance es amplio; desactívalo primero si el renderizado falla o el audio se desfasa.",
