                    ["render.clock.experimental"] = "Relógio de renderização determinístico (experimental)",
                    ["render.clock.hint"] = "Substitui a fonte de tempo que o jogo lê por um relógio virtual movido pelo índice de quadro, tornando determinísticos o avanço dos tempos, os eventos de câmera, as contagens regressivas e o agendamento dos sons de tecla — a taxa de quadros de saída fica constante independentemente da carga da máquina. Desativado = fallback pelo cursor de áudio: a renderização ainda funciona, mas a linha do tempo é conduzida pelo cursor de áudio (oscilação de milissegundos) e os fundos de vídeo não são mais sincronizados à taxa de renderização. Observação: isto altera a própria fonte de tempo do jogo, então seu alcance é maior que o de outras opções; quando outro mod de renderização de vídeo está ativado ao mesmo tempo, ambos disputam o mesmo ponto de patch (o primeiro a carregar vence) e esta opção cede automaticamente. Se a renderização falhar ou houver dessincronia de áudio/vídeo, desative isto primeiro.",
