                    ["about.debug.skipverify.tip"] = "Ignora a verificação de integridade do replay e do áudio. Só é necessário se o arquivo foi modificado ou se o tempo de quadro difere do da gravação (shaders ou fonte de tempo alterados). Não ative se nada está quebrado: é a primeira defesa contra replays corrompidos.",
                    ["about.debug.hidetext.tip"] = "Não mostra os avisos da parte inferior. Útil ao gravar vídeo, capturar imagens limpas ou quando sua própria saída de depuração atrapalha; em troca, falhas silenciosas, como uma ação sem efeito, também passam sem aviso.",
                    ["about.debug.noencryption.tip"] = "Salva os replays como .psprp sem criptografia para inspecionar o conteúdo com ferramentas comuns. O mod continua carregando-os, mas eles não têm proteção de integridade (qualquer um pode editar): não use para compartilhar nem como backup.",
