                    ["about.debug.skipverify.tip"] = "Ignore la vérification d'intégrité du replay et de l'audio. Nécessaire seulement si le fichier a été modifié ou si le timing des images diffère de l'enregistrement (shaders ou source de temps modifiés). À laisser désactivé si rien ne cloche : c'est la première défense contre les replays corrompus.",
