                    ["playback.cloud.failed"] = "Échec de l'opération cloud : {0}",
                    ["playback.cloud.list"] = "Replays dans le cloud",
                    ["playback.cloud.list.note"] = "Cliquez sur un nom pour afficher ses détails ; le bouton Lecture le lit directement depuis le cloud, sans rien écrire dans votre dossier local de replays.",
                    ["playback.cloud.none"] = "Aucune rediffusion à récupérer depuis le cloud.",
                    ["playback.cloud.note"] = "Chaque rediffusion est envoyée avec son son de clavier. Steam ne transfère réellement les fichiers qu'à la fermeture du jeu, donc un replay tout juste enregistré n'apparaîtra pas immédiatement dans le cloud ; après un changement de PC ou une réinstallation, le premier lancement les restaure automatiquement.",
                    ["playback.cloud.play.nosound"] = "{0} a été chargé depuis le cloud, mais le son des touches y manque : cette lecture n'aura pas de son de touches.",
                    ["playback.cloud.restore"] = "Récupérer depuis le cloud",
                    ["playback.cloud.restore.tip"] = "Récupère depuis le cloud les replays absents en local, en comparant les noms de fichiers ; ceux déjà présents ne sont pas touchés. Nécessite une sauvegarde dans le cloud ; le bouton est grisé si Steam Cloud est indisponible.",
                    ["playback.cloud.restoreonload"] = "Restaurer au démarrage",
                    ["playback.cloud.restoreonload.tip"] = "À chaque lancement, compare avec le cloud et restaure les replays absents en local ; les fichiers du même nom ne sont pas écrasés. Sans effet tant que la synchronisation est désactivée.",
                    ["playback.cloud.restored"] = "{0} rediffusions récupérées depuis le cloud.",
