                    ["about.debug.oldhit"] = "Alte Trefferbewertung verwenden",
                    ["about.debug.skipverify.tip"] = "Überspringt die Integritätsprüfung von Replay und Audio. Nur nötig, wenn die Datei verändert wurde oder das Frame-Timing von der Aufnahme abweicht (Shader- oder Zeitquellen-Änderungen). Bei intakten Dateien aus lassen, denn es ist die erste Verteidigung gegen beschädigte Replays.",
                    ["about.debug.hidetext.tip"] = "Blendet die Meldungen am unteren Rand aus. Nützlich beim Aufnehmen von Videos, für saubere Screenshots oder wenn eigene Debug-Ausgaben stören; dafür bleiben stille Fehler wie eine Aktion ohne Wirkung ebenfalls unbemerkt.",
                    ["about.debug.noencryption.tip"] = "Speichert Replays unverschlüsselt als .psprp, damit sich der Inhalt mit normalen Werkzeugen ansehen lässt. Der Mod lädt sie weiterhin, aber ohne Integritätsschutz (jeder kann sie ändern), also nicht zum Weitergeben oder als Sicherung verwenden.",
