                    ["effects.on"] = "Effektentfernung aktivieren",
                    ["effects.on.note"] = "Entfernt die folgenden Effekte aus dem Chart, wenn ein Level geladen wird. Dies betrifft nur die In-Memory-Daten dieses Laufs, nicht die Datei auf der Festplatte, es sei denn, du aktivierst unten das Überschreiben von Speicherungen.",
                    ["effects.enablesave"] = "Überschreiben von Speicherungen erlauben",
                    ["effects.enablesave.note"] = "Solange die Effektentfernung aktiv ist, verweigert der Editor standardmäßig das Speichern. Sonst würde eine Vorschau im Editor und anschließendes Speichern das bereinigte Chart über die Originaldatei schreiben. Aktiviere dies nur, wenn du sie wirklich überschreiben willst.",
                    ["effects.filters"] = "Filter und Blitze",
