                    ["effects.removealldecor"] = "Alle Dekorationen entfernen",
                    ["effects.decor.note"] = "Bei ausgeschaltetem „Alle Dekorationen entfernen“ bleiben Dekorationen erhalten, auf die bedingte Ereignisse verweisen. Sonst würden diese Zweige nie auslösen und das Chart sähe kaputt aus.",
