                    ["playback.cloud.none"] = "In der Cloud gibt es keine Wiederholungen zum Wiederherstellen.",
                    ["playback.cloud.note"] = "Jede Wiederholung wird zusammen mit ihrem Tastenton hochgeladen. Steam überträgt Dateien erst beim Schließen des Spiels, daher erscheint eine gerade aufgenommene Wiederholung nicht sofort in der Cloud; nach einem PC-Wechsel oder einer Neuinstallation werden sie beim ersten Start automatisch wiederhergestellt.",
