                    ["effects.enablesave"] = "Zezwól na nadpisywanie zapisów",
                    ["effects.enablesave.note"] = "Gdy usuwanie efektów jest włączone, edytor domyślnie odmawia zapisu. W przeciwnym razie jednorazowy podgląd w edytorze i zapis zapisałyby oczyszczoną mapę w oryginalnym pliku. Włącz to tylko wtedy, gdy naprawdę chcesz nadpisać mapę.",
