                    ["effects.repeatevents"] = "Zdarzenia powtórzenia",
                    ["effects.gameplay.note"] = "Ta grupa zmienia samą rozgrywkę. Bez punktów kontrolnych lub zdarzeń wejścia mapa nie jest już tym samym co oryginał. Włączaj to tylko wtedy, gdy chcesz po prostu popatrzeć na tory.",
                    ["effects.on.tip"] = "Główny przełącznik. Po wyłączeniu wczytana mapa dokładnie odpowiada oryginalnym danym; nie zostanie usunięte ani jedno zdarzenie.",
                    ["effects.enablesave.tip"] = "Pozwala zapisać bieżącą mapę na dysku, gdy usuwanie efektów jest aktywne. Domyślnie wyłączone: nadpisuje oryginalny plik i nie da się tego cofnąć.",
                    ["effects.filters.tip"] = "Usuwa pełnoekranowe filtry, takie jak błysk, wstrząs ekranu, kalejdoskop, bloom i kafelkowanie ekranu.",
                    ["effects.advfilters.tip"] = "Usuwa zdarzenia filtrów zaawansowanych. Oddzielone od zwykłych filtrów powyżej, aby można było zachować tylko jeden rodzaj.",
                    ["effects.particles.tip"] = "Usuwa zdarzenia dodające, emitujące lub konfigurujące cząstki.",
                    ["effects.backgrounds.tip"] = "Usuwa własne tła i czyści wideo tła, pozostawiając jednolity kolor.",
