                    ["render.clock.experimental"] = "Deterministické hodiny vykreslování (experimentální)",
                    ["render.clock.hint"] = "Nahrazuje zdroj času, který hra čte, virtuálními hodinami řízenými číslem snímku, takže posun taktů, události kamery, odpočty a plánování zvuků kláves jsou deterministické — výstupní snímková frekvence zůstává konstantní bez ohledu na zatížení stroje. Vypnuto = záložní kurzor zvuku: vykreslování stále funguje, ale časovou osu řídí kurzor zvuku (kolísání v řádu milisekund) a videopozadí už není rychlostně sladěné s tempem vykreslování. Poznámka: mění to samotný zdroj času hry, takže dopad je širší než u jiných možností; když je současně zapnutý jiný mod pro vykreslování videa, oba soupeří o stejný bod záplaty (vyhraje první načtený) a tato možnost automaticky ustoupí. Pokud vykreslování hlásí chyby nebo se zvuk a obraz rozcházejí, nejprve toto vypněte.",
