                    ["record.cancelsave.tip"] = "Zahodí klávesovou zkratkou čekající uložení aktuálního běhu. Když to vypneš, zkratka níže nic nedělá.",
                    ["record.asyncinput.tip"] = "Čte klávesy z asynchronního vstupu hry pro přesnější časová razítka. Nejprve je nutné zapnout tuto možnost v nastavení hry, jinak se nic nestane.",
                    ["record.keybd.record.tip"] = "Nahraje ťuknutí jako samostatnou stopu, takže přehrávání má zvuky kláves.",
