                    ["record.keybd.offset.tip"] = "Kalibruje zvuk klávesnice jako celek: záporné, pokud je brzy, kladné, pokud pozdě, v milisekundách.",
                    ["record.keybd.compact.tip"] = "Po zapnutí se zvuk klávesnice ukládá do souboru replaye v 8 kHz — zhruba poloviční velikost a mírně tlumenější. Výchozí je 16 kHz. Týká se jen replayů uložených poté.",
                    ["record.savekey.tip"] = "Zkratka pro uložení tohoto běhu, ve výchozím stavu F9. Klikněte na ni a stiskněte libovolnou klávesu pro nové přiřazení.",
                    ["record.cancelsavekey.tip"] = "Zkratka, která zahodí čekající uložení tohoto běhu.",
                    ["render.on.tip"] = "Hlavní přepínač vykreslování videa. Když je vypnutý, nelze spustit nové vykreslování.",
                    ["render.width.tip"] = "Výstupní šířka. Používá ji jen čistá kamera; obrazovka hry sleduje velikost okna.",
                    ["render.height.tip"] = "Výstupní výška. Používá ji jen čistá kamera.",
                    ["render.fps.tip"] = "Výstupní snímková frekvence. Vyšší = plynulejší, doba vykreslování roste úměrně.",
                    ["render.tail.tip"] = "Další sekundy nahrávané po konci úrovně, aby se zachovala závěrečná animace.",
                    ["render.surface.tip"] = "Zdroj snímků. Čistá kamera nemá UI a má libovolné rozlišení; obrazovka hry obsahuje UI a sleduje okno.",
                    ["render.cursor.tip"] = "Kreslí kurzor myši do videa. Nově nahrané replayy ukládají i dráhu kurzoru, která se při renderu přehrává podle časové osy skladby — je synchronní s obrazem a nezávislá na rychlosti renderu. Starší replayy dráhu nemají a použijí živý kurzor z doby renderu (jeho tempo odpovídá rychlosti renderu). Skrytý kurzor se nekreslí.",
                    ["render.codec.tip"] = "Volba kodéru. Nejrychlejší preferuje kódování na GPU a při neúspěšné kontrole se vrací k CPU; řádek níže ukazuje, který se skutečně používá.",
                    ["render.quality.tip"] = "Kvalita kódování. Vyšší dává větší soubory a mírně delší vykreslování.",
                    ["render.format.tip"] = "Kontejner výstupního souboru. mp4 je nejkompatibilnější; webm je menší, ale vyžaduje překódování.",
                    ["render.outdir.tip"] = "Kam se ukládají hotová videa. Prázdné = RenderVideos ve složce modu.",
                    ["render.clock.experimental.tip"] = "Nahrazuje zdroj času hry virtuálními hodinami řízenými číslem snímku, aby výstupní snímková frekvence byla konstantní bez ohledu na zatížení stroje. Mění samotný zdroj času hry, takže dopad je široký; pokud vykreslování hlásí chyby nebo se zvuk rozchází, nejprve toto vypněte.",
                    ["convert.target.tip"] = "Převede existující videa ve výstupní složce do tohoto formátu, nezávisle na formátu vykreslování výše.",
                    ["render.start.tip"] = "Spustí vykreslování s aktuálním nastavením. Nejprve načtěte záznam a vstupte do jeho úrovně.",
                    ["render.cancel.tip"] = "Přeruší aktuální vykreslování. Co už bylo zapsáno, zůstane.",
                    ["convert.button.tip"] = "Spustí dávkový převod videí ve výstupní složce.",
                    ["record.changedir.tip"] = "Změnit složku záznamů. Během nahrávání není povoleno, jinak by se zvuk klávesnice tohoto běhu ztratil.",
