                    ["record.keymap.off.tip"] = "Vysvětluje aktuální stav: tabulka se ignoruje.",
                    ["record.keymap.note"] = "Vlevo je kód, který klávesa skutečně odesílá, vpravo klávesa, kterou má hra vidět. Klikněte na políčko a stiskněte libovolnou klávesu pro přiřazení; Esc zruší.",
