                    ["effects.repeatevents"] = "Повторяющиеся события",
                    ["effects.gameplay.note"] = "Эта группа меняет саму игру. Без контрольных точек или событий ввода карта уже не то же самое, что оригинал. Включайте это, только если просто хотите посмотреть на дорожки.",
                    ["effects.on.tip"] = "Общий переключатель. Когда он выключен, загруженная карта в точности соответствует исходным данным; не убирается ни одно событие.",
                    ["effects.enablesave.tip"] = "Позволяет записать текущую карту на диск, пока удаление эффектов активно. По умолчанию выключено: это перезаписывает исходный файл, и отменить это нельзя.",
                    ["effects.filters.tip"] = "Убирает полноэкранные фильтры, такие как вспышка, тряска экрана, зеркальный коридор, bloom и тайлинг экрана.",
                    ["effects.advfilters.tip"] = "Убирает события продвинутых фильтров. Отдельно от обычных фильтров выше, чтобы можно было оставить только один вид.",
                    ["effects.particles.tip"] = "Убирает события добавления, испускания и настройки частиц.",
                    ["effects.backgrounds.tip"] = "Убирает свои фоны и очищает фоновое видео, оставляя ровный цвет.",
                    ["effects.cameras.tip"] = "Убирает события движения камеры, так что камера остаётся на месте.",
                    ["effects.setcamerazoom.tip"] = "Фиксирует камеру на заданном зуме после удаления движений. Зум ниже ничего не делает, пока это выключено.",
                    ["effects.camerazoom.tip"] = "Уровень зума, на котором фиксируется камера. Работает только при включённом выше «Задать зум камеры».",
                    ["effects.decorations.tip"] = "Удаляет из карты декорации, текст и пользовательские объекты.",
                    ["effects.removealldecor.tip"] = "Очищает все декорации. Когда выключено, декорации, на которые ссылаются условные события, сохраняются.",
                    ["effects.trackanim.tip"] = "Убирает анимации появления/исчезновения дорожек, так что дорожки появляются сразу.",
                    ["effects.trackpos.tip"] = "Убирает события позиции дорожек.",
                    ["effects.trackmove.tip"] = "Убирает события движения дорожек — самый частый вид движения дорожек.",
                    ["effects.trackcolor.tip"] = "Убирает события цвета дорожек, так что дорожки сохраняют один цвет.",
                    ["effects.resettrackopacity.tip"] = "Возвращает непрозрачность оставшихся событий движения дорожек к 100%.",
                    ["effects.resettrackanim.tip"] = "Заменяет анимации появления/исчезновения дорожек затуханием, чтобы дорожки не пропадали после удаления их анимаций.",
                    ["effects.resettrackcolor.tip"] = "Возвращает стиль и цвет дорожки к стандартной оранжевой дорожке по умолчанию.",
                    ["effects.toggleall.tip"] = "Если в этой группе что-то включено, одно нажатие выключит всё; если всё выключено, одно нажатие включит всё. Затрагиваются только переключатели, убирающие свой тип событий; сбросы и сопутствующие параметры не входят.",
                    ["effects.planetorbit.tip"] = "Убирает события вращения планеты.",
                    ["effects.planetscale.tip"] = "Убирает события масштаба планеты.",
                    ["effects.planetradius.tip"] = "Убирает события радиуса планеты.",
                    ["effects.hideicons.tip"] = "Убирает события скрытия значков.",
                    ["effects.hitsounds.tip"] = "Убирает звуки попаданий и события пользовательских звуков. Песня становится тихой.",
                    ["effects.holdsounds.tip"] = "Убирает события звуков удержания.",
                    ["effects.checkpoints.tip"] = "Убирает контрольные точки, так что неудача посреди уровня возвращает вас в начало.",
                    ["effects.inputevents.tip"] = "Убирает события ввода, такие как автовоспроизведение и ограничения клавиш.",
                    ["effects.framerate.tip"] = "Убирает события смены частоты кадров, так что весь уровень идёт в одном темпе.",
                    ["effects.repeatevents.tip"] = "Убирает повторяющиеся события. Разделы, которые карта переиспользует через них, разворачиваются один раз.",
                    ["record.recording.tip"] = "Общий переключатель. Когда выключен, вход на уровень ничего не записывает.",
                    ["record.autosave.tip"] = "Сохраняет этот прогон как файл повтора при завершении уровня.",
                    ["record.completesave.tip"] = "Сохранять только полные прохождения. Выключите, чтобы сохранять и брошенные на середине прогоны.",
                    ["record.dontsavewhenauto.tip"] = "Пропускает уровни, которые игра прошла сама, чтобы автоигра не забивала список повторов.",
                    ["record.dontsavewhenmiss.tip"] = "Пропускает прогоны с промахом. Выключите, чтобы сохранить неудачную попытку.",
                    ["record.latesave.tip"] = "Сохранять при выходе с уровня, а не на экране результатов.",
                    ["record.failsave.tip"] = "Сохранять и при смерти. По умолчанию файл пишется только при прохождении или ручном сохранении.",
                    ["record.backup.tip"] = "Хранить дополнительную копию при сохранении, чтобы существующий файл не был просто перезаписан.",
                    ["record.manualsave.tip"] = "Включает F9 для ручного сохранения текущего прогона, в том числе попытки в тренировке.",
                    ["record.cancelsave.tip"] = "Отбрасывает по горячей клавише отложенное сохранение текущего прогона. Если выключить, клавиша ниже перестанет работать.",
                    ["record.asyncinput.tip"] = "Брать клавиши из асинхронного ввода игры для более точных меток времени. Сначала нужно включить эту опцию в настройках игры, иначе ничего не произойдёт.",
                    ["record.keybd.record.tip"] = "Записывать стук отдельной дорожкой, чтобы при воспроизведении были звуки клавиш.",
                    ["record.keybd.volume.tip"] = "Громкость звука клавиатуры при воспроизведении. 0 = без звука.",
                    ["record.keybd.offset.tip"] = "Калибрует звук клавиатуры целиком: отрицательное, если он раньше, положительное, если позже, в миллисекундах.",
                    ["record.keybd.compact.tip"] = "Если включено, звук клавиатуры сохраняется в файл повтора с частотой 8 кГц — примерно вдвое меньше по размеру и чуть глуше. По умолчанию 16 кГц. Действует только на повторы, сохранённые после этого.",
                    ["record.savekey.tip"] = "Горячая клавиша для сохранения этого прогона, по умолчанию F9. Нажмите на неё, затем нажмите любую клавишу, чтобы переназначить.",
                    ["record.cancelsavekey.tip"] = "Горячая клавиша, отменяющая ожидающее сохранение этого прогона.",
                    ["render.on.tip"] = "Общий переключатель видеорендера. Когда он выключен, новый рендер запустить нельзя.",
                    ["render.width.tip"] = "Выходная ширина. Используется только чистой камерой; экран игры следует размеру окна.",
                    ["render.height.tip"] = "Выходная высота. Используется только чистой камерой.",
                    ["render.fps.tip"] = "Частота кадров на выходе. Выше = плавнее, а время рендера растёт пропорционально.",
                    ["render.tail.tip"] = "Дополнительные секунды записи после конца уровня, чтобы сохранить финальную анимацию.",
                    ["render.surface.tip"] = "Источник кадров. Чистая камера без UI и с любым разрешением; экран игры включает UI и следует за окном.",
                    ["render.cursor.tip"] = "Рисует курсор мыши в видео. В свежезаписанных реплеях сохраняется и траектория курсора: при рендере она воспроизводится по таймлайну песни — синхронно с картинкой и независимо от скорости рендера. В старых реплеях траектории нет, и используется живой курсор на момент рендера (его темп следует скорости рендера). Скрытый курсор не рисуется.",
                    ["render.codec.tip"] = "Выбор кодека. «Самый быстрый» предпочитает аппаратное кодирование GPU и откатывается на CPU при неудачной проверке; строка ниже показывает, какой используется фактически.",
                    ["render.quality.tip"] = "Качество кодирования. Выше — больше файлы и чуть дольше рендер.",
                    ["render.format.tip"] = "Контейнер выходного файла. mp4 самый совместимый; webm меньше, но требует перекодирования.",
                    ["render.outdir.tip"] = "Куда попадают готовые видео. Пусто = RenderVideos в папке мода.",
                    ["render.clock.experimental.tip"] = "Заменяет источник времени игры на виртуальные часы, управляемые номером кадра, чтобы частота кадров на выходе была постоянной независимо от нагрузки на машину. Меняет сам источник времени игры, поэтому последствия широки; сначала выключите это, если рендер выдаёт ошибки или звук расходится.",
                    ["convert.target.tip"] = "Конвертирует существующие видео в папке вывода в этот формат независимо от формата рендера выше.",
                    ["render.start.tip"] = "Запускает рендер с текущими настройками. Сначала загрузите повтор и войдите на его уровень.",
                    ["render.cancel.tip"] = "Прерывает текущий рендер. Уже записанное сохраняется.",
                    ["convert.button.tip"] = "Запускает пакетную конвертацию видео в папке вывода.",
                    ["record.changedir.tip"] = "Сменить папку повторов. Недоступно во время записи, иначе звук клавиатуры этого прогона потеряется.",
                    ["record.keymap"] = "Переназначение клавиш",
                    ["record.keymap.tip"] = "Сопоставляет код одной клавиши с другой. Полезно для геймпадов, клавиатур с макросами или утилит переназначения, чьи коды отличаются от стандартных клавиш, которые ожидает игра.",
                    ["record.keymap.on"] = "Включить переназначение клавиш",
                    ["record.keymap.on.tip"] = "Главный переключатель. Когда выключено, клавиши записываются и воспроизводятся как есть, а таблица ниже не действует.",
                    ["record.keymap.off"] = "Переназначение выключено; клавиши используются как есть.",
                    ["record.keymap.off.tip"] = "Поясняет текущее состояние: таблица игнорируется.",
                    ["record.keymap.note"] = "Слева — код, который клавиша фактически отправляет, справа — клавиша, которую должна увидеть игра. Щёлкните ячейку и нажмите любую клавишу, чтобы назначить; Esc отменяет.",
                    ["record.keymap.note.tip"] = "Поясняет, как пользоваться этой таблицей.",
                    ["record.keymap.empty"] = "Ещё нет записей. Используйте кнопку ниже, чтобы добавить.",
                    ["record.keymap.empty.tip"] = "Поясняет, что таблица пуста.",
                    ["record.keymap.add"] = "Добавить запись",
                    ["record.keymap.add.tip"] = "Добавляет пустую строку; затем назначьте обе стороны, щёлкнув по ним.",
                    ["ui.keymap.none"] = "Не назначено",
                    ["ui.keymap.none.tip"] = "Этой ячейке ещё не назначена ни одна клавиша.",
                    ["ui.keymap.clear"] = "Очистить",
                    ["ui.keymap.clear.tip"] = "Очистка целевой клавиши означает, что эта клавиша вообще не даёт ввода (простой способ заблокировать одну клавишу). Левая запись остаётся в таблице.",
                    ["ui.keymap.delete"] = "Удалить",
                    ["ui.keymap.delete.tip"] = "Удаляет эту строку из таблицы.",
                    ["record.keymap.limit"] = "Симулировать только клавиши из списка",
                    ["record.keymap.limit.tip"] = "Когда включено, клавиши, которых нет в таблице, вообще не дают ввода. Используйте, чтобы заблокировать все клавиши, кроме нескольких на геймпаде или клавиатуре с макросами. Учтите, что многие клавиши молча перестанут работать.",
                    ["playback.cloud"] = "Резервная копия в Steam Cloud",
                    ["playback.cloud.delete.tip"] = "Удаляет только эту копию из облака (вместе со звуком клавиш); локальный файл остаётся. Для подтверждения нужно два клика.",
                    ["playback.cloud.deleted"] = "Удалено из облака: {0}",
                    ["playback.cloud.download"] = "Скачать",
                    ["playback.cloud.download.exists"] = "Этот повтор уже есть в локальной папке; ничего не перезаписано.",
                    ["playback.cloud.download.tip"] = "Записывает этот повтор из облака (вместе со звуком клавиш) в локальную папку повторов; существующие файлы никогда не перезаписываются.",
                    ["playback.cloud.downloaded"] = "Скачано в локальную папку: {0}",
                    ["playback.cloud.upload.exists"] = "Этот повтор уже есть в облаке.",
                    ["playback.cloud.upload.one"] = "Загрузить",
                    ["playback.cloud.upload.one.tip"] = "Отправляет этот локальный повтор (вместе со звуком клавиш) в облако.",
                    ["playback.cloud.uploaded.one"] = "Загружено в облако: {0}",
                    ["playback.cloud.err.unavailable"] = "Steam Cloud недоступен",
                    ["playback.cloud.err.unreadable"] = "этот повтор не читается (возможно, он повреждён)",
                    ["playback.cloud.err.notfound"] = "этого файла больше нет в облаке",
